#include <vector>
#include <iostream>
#include <type_traits>

int main() {
    // std::vector<bool> uses specialization for memory savings
    std::vector<bool> flags(1000);

    // Generic vector uses at least 1 byte per bool (usually 1 byte)
    std::vector<char> generic_flags(1000);

    // The specialized vector is generally much smaller, 
    // but this size difference cannot be reliably calculated via sizeof()
    // due to internal implementation details.

    flags[500] = true; // Use of proxy reference object
}
